{
 "summary": "The file proves two things. First, there is a finite connected bipartite 2-degenerate graph H on Fin q, with a proper 2-colouring in which each colour class contains a vertex of degree ≥ 3, and constants c, ε > 0 such that c·n^{3/2+ε} ≤ ex(n,H) for all sufficiently large n. Second, it proves the negation of Erdős's degeneracy conjecture: for all r > 0, every bipartite r-degenerate H has ex(n,H) = O(n^{2−1/r}). This matches Theorem 1.2 and is slightly stronger because of the extra max-degree condition. No significant faithfulness caveat was found; the main point to note is that degeneracy is phrased via induced vertex subsets, which is equivalent to the standard subgraph definition.",
 "glossary": [
  {"decl": "neighborsWithin", "line": 8, "plain": "N_G(v) ∩ s, the neighbours of v inside the finite set s", "standard_concept": "neighbourhood restricted to a vertex subset", "matches_standard": "yes", "note": ""},
  {"decl": "IsDegenerate", "line": 13, "plain": "Every nonempty finite vertex set s contains a vertex with at most r neighbours inside s, i.e. every nonempty induced subgraph has minimum degree ≤ r", "standard_concept": "r-degenerate graph", "matches_standard": "yes", "note": "The paper phrases it via subgraphs. It is equivalent to the induced version, since deleting edges only lowers degrees."},
  {"decl": "IsTwoDegenerate", "line": 17, "plain": "2-degenerate", "standard_concept": "2-degenerate graph", "matches_standard": "yes", "note": ""},
  {"decl": "DegeneracyConjectureStatement", "line": 20, "plain": "For all r > 0 and every bipartite r-degenerate finite graph H, ex(n,H) = O(n^{2−1/r}) as n → ∞", "standard_concept": "Erdős degeneracy conjecture (3)", "matches_standard": "yes", "note": "r > 0 avoids the 1/0 junk value; extremalNumber is Mathlib's ex(n,H) on Fin n."}
 ],
 "lean_claims": [
  {"theorem": "twoDegenerateExtremalCounterexample", "line": 28, "plain": "There exist q and a graph H on Fin q satisfying all of the following: H is connected; H is bipartite; H is 2-degenerate; some proper 2-colouring of H has, in each colour class, maximum degree > 2; and there are c, ε > 0 such that c·n^{3/2+ε} ≤ ex(n,H) for all sufficiently large n."},
  {"theorem": "not_erdos_146", "line": 43, "plain": "It is not the case that for every r > 0 and every bipartite r-degenerate finite graph H, ex(n,H) = O(n^{2−1/r})."}
 ],
 "paper_claims": [
  {"ref": "Theorem 1.2", "plain": "There exist a fixed connected bipartite 2-degenerate graph H and constants c, ε > 0 with ex(n,H) ≥ c·n^{3/2+ε} for all sufficiently large n."},
  {"ref": "Abstract / Section 1.2", "plain": "Erdős's conjecture that every bipartite r-degenerate H has ex(n,H) = O(n^{2−1/r}) is false (already for r = 2)."},
  {"ref": "Theorem 1.1", "plain": "Failure of the compactness conjecture (covered elsewhere, sibling file)."}
 ],
