  {"paper_ref": "Abstract / Section 1.2", "lean_theorem": "not_erdos_146", "relation": "equivalent", "why": "Negation of a faithful formalization of conjecture (3)."},
  {"paper_ref": "Theorem 1.1", "lean_theorem": null, "relation": "not_formalized", "why": "Covered elsewhere (sibling file J_CompactnessConjecture)."}
 ],
